// src/content/docs/docs/project/changelog.md from the repository's CHANGELOG.md.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { ROOT, SITE } from './lib.ts';

const source = readFileSync(join(ROOT, 'CHANGELOG.md'), 'utf8');
const body = source.slice(source.indexOf('\n## ')).trim();
writeFileSync(join(SITE, 'src/content/docs/docs/project/changelog.md'), `---
title: Changelog
description: What changed in each ReverseDock release.
sidebar:
  order: 2
---

<!-- Generated by scripts/gen-changelog.ts from CHANGELOG.md. Do not edit by hand. -->

${body}
`);
console.log('changelog: copied');
